<style>
.qd{--qd-bg:#fff;--qd-soft:#f8fafc;--qd-line:#e2e8f0;--qd-text:#1e293b;--qd-muted:#64748b;--qd-tint:#eff8ff;direction:rtl;max-width:1240px;margin:0 auto 40px;color:var(--qd-text);font-family:'Cairo',sans-serif}
.qd *{box-sizing:border-box}.qd [x-cloak]{display:none!important}.qd p{line-height:1.9}.qd button,.qd input,.qd select,.qd textarea{font-family:inherit}.qd button,.qd a{touch-action:manipulation}.qd a:focus-visible,.qd button:focus-visible{outline:3px solid #38bdf8;outline-offset:4px}.qd-back{display:inline-flex;align-items:center;gap:8px;color:var(--qd-muted);font-size:13px;text-decoration:none;margin-bottom:18px}.qd-back:hover{color:#0071aa}
.qd-hero{display:flex;align-items:center;gap:22px;padding:32px;border-radius:22px;background:linear-gradient(115deg,#004b76,#0071aa);color:#fff;margin-bottom:18px;box-shadow:0 8px 24px #0071aa12}.qd-icon{display:grid;place-items:center;width:64px;height:64px;flex-shrink:0;border-radius:19px;background:#ffffff18;border:1px solid #ffffff30;color:#fff}.qd-hero-label{display:block;font-size:11px;font-weight:700;letter-spacing:.04em;color:#bae6fd;margin-bottom:8px}.qd h1{font-size:26px;font-weight:800;margin:0 0 8px;line-height:1.5}.qd-hero p{margin:0;font-size:13px;color:#e0f2fe}
.qd-nav{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:8px;border:1px solid var(--qd-line);border-radius:15px;background:var(--qd-bg);margin-bottom:24px}.qd-nav a{display:flex;align-items:center;justify-content:center;gap:10px;padding:12px 8px;border-radius:9px;color:var(--qd-text);font-size:12px;font-weight:700;text-decoration:none}.qd-nav a:hover{background:var(--qd-tint);color:#0071aa}.qd-nav span{color:#0284c7;font-size:11px}
.qd-layout{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:24px;align-items:start}.qd-layout>div{min-width:0}.qd-panel{background:var(--qd-bg);border:1px solid var(--qd-line);border-radius:18px;overflow:hidden;box-shadow:0 4px 18px #0f172a03}.qd-section{padding:30px;scroll-margin-top:100px}.qd-section+.qd-section{border-top:1px solid var(--qd-line)}.qd-heading{display:flex;align-items:center;gap:12px;margin-bottom:22px}.qd-step{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:var(--qd-tint);color:#0284c7;font-size:13px;font-weight:800;flex-shrink:0}.qd h2{margin:0;font-size:16px;font-weight:800;line-height:1.6}
.qd-label{display:block;font-size:12px;font-weight:700;margin-bottom:10px;line-height:1.8;color:var(--qd-text)}.qd-label>.qd-field{display:block;margin-top:8px}.qd-field+.qd-label{margin-top:18px}.qd-optional{color:var(--qd-muted);font-weight:400;font-size:11px}.qd-field{width:100%;min-width:0;min-height:46px;padding:11px 13px;background:var(--qd-bg);border:1px solid var(--qd-line);border-radius:10px;color:var(--qd-text);font-size:13px;font-weight:400;line-height:1.7;transition:border-color .15s,box-shadow .15s}.qd select.qd-field{padding-inline-end:32px}.qd textarea{resize:vertical}.qd-field:hover{border-color:#94a3b8}.qd-field:focus{outline:none;border-color:#0284c7;box-shadow:0 0 0 3px #0284c71a}.qd-field[aria-invalid=true]{border-color:#ef4444}.qd-field::placeholder{color:#94a3b8}.qd-help{font-size:12px;color:var(--qd-muted);margin:10px 0 0}.qd-dates{display:grid;grid-template-columns:1fr 1fr;gap:18px}.qd-dates>*{min-width:0}.qd-note{padding:13px 16px;background:var(--qd-tint);border-inline-start:3px solid #38bdf8;border-radius:8px;color:#0284c7;font-size:12px;margin:18px 0 0}
.qd-preferences{display:grid;grid-template-columns:1fr 1fr;gap:10px;border:0;padding:0;margin:24px 0 0}.qd-preferences legend{font-size:13px;font-weight:800;margin-bottom:14px}.qd-toggle{position:relative;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px;background:var(--qd-soft);border:1px solid var(--qd-line);border-radius:11px;cursor:pointer;font-size:12px}.qd-toggle input{position:absolute;opacity:0;width:1px;height:1px}.qd-switch{width:36px;height:21px;flex-shrink:0;border-radius:20px;background:#94a3b8;position:relative;transition:background .15s}.qd-switch:after{content:'';position:absolute;top:3px;left:3px;width:15px;height:15px;border-radius:50%;background:#fff;transition:transform .15s}.qd-toggle input:checked+.qd-switch{background:#0071aa}.qd-toggle input:checked+.qd-switch:after{transform:translateX(15px)}.qd-toggle input:focus-visible+.qd-switch{outline:3px solid #38bdf8;outline-offset:3px}
.qd-actions{display:flex;flex-wrap:wrap;align-items:center;gap:16px;padding:22px 30px;border-top:1px solid var(--qd-line);background:var(--qd-soft)}.qd-save-note{display:flex;flex-direction:column;gap:5px;flex:1;min-width:180px}.qd-save-note strong{font-size:13px}.qd-save-note span{font-size:11px;color:var(--qd-muted)}.qd-submit{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:46px;padding:11px 22px;border:0;border-radius:10px;background:#0071aa;color:white;font-size:13px;font-weight:700;cursor:pointer;box-shadow:0 4px 10px #0071aa20}.qd-submit:hover{background:#005b89}.qd-submit:disabled{opacity:.65;cursor:wait}.qd-cancel{color:var(--qd-muted);font-size:12px;text-decoration:none;cursor:pointer}.qd-actions>.qd-cancel{padding:12px}.qd-summary{position:sticky;top:100px;padding:24px;border-top:3px solid #0071aa}.qd-eyebrow{font-size:11px;font-weight:700;color:#0284c7;margin-bottom:12px}.qd-title{font-size:17px;font-weight:800;line-height:1.8;overflow-wrap:anywhere;margin-bottom:18px}.qd-stat{display:flex;justify-content:space-between;gap:12px;padding:14px 0;font-size:12px;border-bottom:1px solid var(--qd-line)}.qd-stat span{color:var(--qd-muted)}.qd-stat strong{font-weight:700}.qd-summary-note{background:#f0fdf4;color:#15803d;border:1px solid #dcfce7;border-radius:10px;padding:13px;font-size:12px;margin:18px 0 0}
.qd-question{border:1px solid var(--qd-line);border-radius:14px;margin-top:22px;overflow:hidden;background:var(--qd-bg)}.qd-question-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 20px;background:var(--qd-soft);border-bottom:1px solid var(--qd-line)}.qd-question-head h2{font-size:14px}.qd-question-body{padding:20px}.qd-danger{display:inline-flex;align-items:center;gap:5px;min-height:36px;padding:6px 10px;border:1px solid #fecaca;border-radius:8px;color:#b91c1c;background:#fff7f7;font-size:11px;cursor:pointer}.qd-danger:hover{background:#fee2e2}.qd-options{padding:16px;background:var(--qd-soft);border:1px solid var(--qd-line);border-radius:12px;margin:18px 0}.qd-option{border:1px solid var(--qd-line);border-radius:10px;background:var(--qd-bg);padding:14px;margin-bottom:12px}.qd-option-correct{border-color:#86efac;box-shadow:inset -3px 0 #22c55e}.qd-option-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.qd-option-footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.qd-option-footer .qd-label{display:flex;align-items:center;gap:10px;margin:0;flex:1}.qd-option-footer select{max-width:145px;margin:0}.qd-add{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;min-height:44px;padding:12px;border:1px dashed #7dd3fc;background:var(--qd-tint);color:#0284c7;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer}.qd-add:hover{border-style:solid}.qd-question-count{margin-inline-start:auto;background:var(--qd-tint);color:#0284c7;border-radius:20px;padding:5px 12px;font-size:11px;white-space:nowrap}
.qd-error{padding:16px 20px;border:1px solid #fecaca;background:#fef2f2;color:#b91c1c;border-radius:12px;margin-bottom:20px;font-size:13px}.qd-error p{margin:0}.qd-empty{text-align:center;padding:44px 24px}.qd-empty p{color:var(--qd-muted);font-size:13px}
.dark .qd{--qd-bg:#111827;--qd-soft:#172033;--qd-line:#334155;--qd-text:#e2e8f0;--qd-muted:#94a3b8;--qd-tint:#082f49}.dark .qd-summary-note{background:#052e24;border-color:#14532d;color:#86efac}.dark .qd-danger{background:#450a0a;border-color:#7f1d1d;color:#fca5a5}.dark .qd-option-correct{border-color:#15803d}
@media(max-width:1100px){.qd-layout{grid-template-columns:minmax(0,1fr) 240px;gap:18px}.qd-section{padding:24px}.qd-summary{padding:20px}.qd-preferences{grid-template-columns:1fr}}
@media(max-width:900px){.qd-layout{grid-template-columns:1fr}.qd-summary{position:static;display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.qd-summary .qd-eyebrow,.qd-summary .qd-title,.qd-summary .qd-help,.qd-summary-note{grid-column:1/-1}.qd-preferences{grid-template-columns:1fr 1fr}}
@media(max-width:600px){.qd-hero{padding:22px;gap:14px;align-items:flex-start}.qd-icon{width:44px;height:44px;border-radius:12px}.qd h1{font-size:20px}.qd-nav{grid-template-columns:1fr 1fr;gap:4px}.qd-nav a{justify-content:flex-start}.qd-section{padding:22px 16px}.qd-dates,.qd-preferences,.qd-option-grid{grid-template-columns:1fr;gap:12px}.qd-question-body{padding:14px}.qd-question-head{padding:14px}.qd-options{padding:12px}.qd-option-footer{flex-wrap:wrap}.qd-actions{padding:20px 16px;gap:12px}.qd-save-note{flex-basis:100%}.qd-actions>.qd-submit{flex:1}.qd-heading{gap:8px}.qd h2{font-size:14px}.qd-question-count{padding:4px 8px}.qd-summary{display:block}}
.qd-upload{padding:18px;background:var(--qd-soft);border:1px dashed #94a3b8;border-radius:12px;margin:16px 0}.qd-upload input[type=file]{background:var(--qd-bg);font-size:12px}.qd-upload input[type=file]::file-selector-button{background:var(--qd-tint);color:#0284c7;border:0;border-radius:6px;padding:7px 12px;margin-inline-end:12px;cursor:pointer}.qd-image-preview{display:block;max-width:100%;max-height:320px;object-fit:contain;margin:14px auto 0;border-radius:10px;background:#fff}
@media(prefers-reduced-motion:reduce){.qd *{transition:none!important}}
</style>
